    <tr><td style={{ padding: '8px 12px', border: '1px solid rgba(0,0,0,0.12)' }}>Motorcycles x Heavy Trucks</td><td style={{ textAlign: 'right', padding: '8px 12px', border: '1px solid rgba(0,0,0,0.12)' }}>0.690</td><td style={{ textAlign: 'right', padding: '8px 12px', border: '1px solid rgba(0,0,0,0.12)' }}>&lt; .001</td><td style={{ textAlign: 'right', padding: '8px 12px', border: '1px solid rgba(0,0,0,0.12)' }}>***</td></tr>
