    <tr><td style={{ padding: '8px 12px', border: '1px solid rgba(0,0,0,0.12)' }}>Natete Junction</td><td style={{ textAlign: 'right', padding: '8px 12px', border: '1px solid rgba(0,0,0,0.12)' }}>104.6</td><td style={{ textAlign: 'right', padding: '8px 12px', border: '1px solid rgba(0,0,0,0.12)' }}>1,280</td></tr>
